// ── Floating preview sub-component ──────────────────────────────────────────
function FloatingPreview({
  cfg,
  css,
  wid,
  widgetHtml,
  pinIcon,
}: {
  cfg: WidgetConfig;
  css: string;
  wid: string;
  widgetHtml: React.ReactNode;
  pinIcon: React.ReactNode;
}) {
  const [panelOpen, setPanelOpen] = useState(true);

  return (
    <>
      {/* eslint-disable-next-line react/no-danger */}
      <style dangerouslySetInnerHTML={{ __html: css }} />
      {/* Floating layout — panel + trigger, no storefront mockup */}
      <div style={{ display: "flex", flexDirection: "column", gap: 12, alignItems: "flex-end", minHeight: 420, justifyContent: "center" }}>
        {/* Panel */}
        {panelOpen && (
          <div
            style={{
              background: cfg.backgroundColor,
              borderRadius: 14,
              boxShadow: "0 8px 32px rgba(0,0,0,.12), 0 2px 8px rgba(0,0,0,.06)",
              width: "100%",
              overflow: "hidden",
              border: "1px solid rgba(0,0,0,0.06)",
            }}
          >
            {/* Panel header */}
            <div
              style={{
                display: "flex",
                alignItems: "center",
                justifyContent: "space-between",
                padding: "12px 14px",
                background: `linear-gradient(135deg, ${cfg.primaryColor}08, ${cfg.primaryColor}03)`,
                borderBottom: "1px solid rgba(0,0,0,0.06)",
              }}
            >
              <div
                style={{
                  fontSize: 13,
                  fontWeight: 700,
                  color: cfg.textColor,
                  display: "flex",
                  alignItems: "center",
                  gap: 8,
                }}
              >
                <span style={{
                  display: "inline-flex",
                  alignItems: "center",
                  justifyContent: "center",
                  width: 26,
                  height: 26,
                  borderRadius: "50%",
                  background: cfg.primaryColor + "18",
                }}>
                  {pinIcon}
                </span>
                {cfg.heading}
              </div>
              <button
                type="button"
                onClick={() => setPanelOpen(false)}
                style={{
                  background: "rgba(0,0,0,0.05)",
                  border: "none",
                  cursor: "pointer",
                  color: cfg.textColor,
                  borderRadius: 6,
                  width: 24,
                  height: 24,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  padding: 0,
                }}
              >
                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" style={{ width: 14, height: 14 }}>
                  <path d="M18 6L6 18" /><path d="M6 6l12 12" />
                </svg>
              </button>
            </div>
